"""Weekly timesheet rows built from a list of shifts."""

from typing import List

from hourglass.models import Shift


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker with shift count and hours, busiest first."""
    if not shifts:
        raise ValueError("no shifts to build a timesheet from")
    totals = {}
    # Tally shifts and minutes for each worker
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker name")
        count, minutes = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, minutes + shift.span.minutes)
    ranked = sorted(totals.items(), key=lambda item: (-item[1][1], item[0]))
    return [
        f"{name}: {count} shifts, {minutes / 60:.1f} hours"
        for name, (count, minutes) in ranked
    ]

